-- PARTE 1/6: cria _bling_pedido + popula 1ª metade (268 de 535).

DROP TABLE IF EXISTS _bling_match;
DROP TABLE IF EXISTS _bling_item;
DROP TABLE IF EXISTS _bling_pedido;

CREATE TABLE _bling_pedido (
  numero text PRIMARY KEY,
  cliente_nome text, telefone text, endereco text,
  data date, total numeric, desconto numeric,
  forma_pagamento text, observacoes text, trello_id text, tipo text
);

;

;

;

SELECT COUNT(*) AS pedidos_inseridos_parte1 FROM _bling_pedido;